const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};
const authHeader = headers['x-webhook-token'] || headers['authorization'];

const expectedToken = $env.WEBHOOK_SECRET_TOKEN || 'secure_triage_webhook_bearer_token_xyz123';
const cleanAuth = authHeader ? authHeader.replace(/^Bearer\s+/i, '') : '';

if (!cleanAuth || cleanAuth !== expectedToken) {
  return [{
    json: {
      isValid: false,
      errorCode: 401,
      errorMessage: 'Unauthorized: Invalid or missing webhook security token.'
    }
  }];
}

const { idempotency_key, customer_id, customer_email, subject, content } = body;
if (!idempotency_key || !customer_email || !subject || !content) {
  return [{
    json: {
      isValid: false,
      errorCode: 400,
      errorMessage: 'Bad Request: Missing required fields (idempotency_key, customer_email, subject, content).'
    }
  }];
}

return [{
  json: {
    isValid: true,
    data: {
      idempotency_key: String(idempotency_key).trim(),
      customer_id: customer_id ? String(customer_id).trim() : 'anonymous',
      customer_email: String(customer_email).trim().toLowerCase(),
      subject: String(subject).trim().slice(0, 255),
      content: String(content).trim()
    }
  }
}];

const payload = $('Validate Auth & Schema').first().json.data;
const combinedText = `${payload.subject} ${payload.content}`.toLowerCase();

let category = 'general';
let urgency = 'normal';
let sentiment = 'neutral';
let assigned_tier = 'tier_1_bot';
let automated_response = null;

if (combinedText.includes('password') || combinedText.includes('login') || combinedText.includes('credentials')) {
  category = 'auth';
  urgency = 'normal';
  sentiment = 'neutral';
  assigned_tier = 'tier_1_bot';
  automated_response = 'You can reset your corporate credentials at https://app.example.com/forgot-password. A 15-minute OTP has been initiated.';
} else if (combinedText.includes('invoice') || combinedText.includes('billing') || combinedText.includes('charge') || combinedText.includes('refund')) {
  category = 'billing';
  urgency = 'high';
  sentiment = 'urgent';
  assigned_tier = 'tier_2_human';
} else if (combinedText.includes('down') || combinedText.includes('outage') || combinedText.includes('exploit') || combinedText.includes('breach') || combinedText.includes('urgent')) {
  category = 'incident';
  urgency = 'critical';
  sentiment = 'urgent';
  assigned_tier = 'security_escalation';
}

return [{
  json: {
    ...payload,
    category,
    urgency,
    sentiment,
    assigned_tier,
    resolution_status: assigned_tier === 'tier_1_bot' ? 'resolved' : 'pending_human',
    automated_response
  }
}];
